export async function createApiToken(actor: Actor, input: CreateApiTokenInput): Promise<{ token: string; apiToken: ApiToken }> {
  const data = createApiTokenSchema.parse(input);
  assertOrgScope(actor, data.orgId);
  if (data.scope === \"write\") assertCan(actor, \"project:create\", { kind: \"organization\", orgId: data.orgId });
  const now = new Date();
  const token = "'`tfk_${randomToken()}`;
  const apiToken = await tokens.insertToken({
    id: newId(), orgId: data.orgId, userId: actor.userId, name: data.name, scope: data.scope,
    prefix: token.slice(0, 12), createdAt: toIsoTimestamp(now),
    expiresAt: toIsoTimestamp(new Date(now.getTime() + data.expiresInDays * 86400000)),
    lastUsedAt: null, revokedAt: null,
  }, hashToken(token));
  await emit("api_token.created", { ...actorEnvelope(actor), tokenId: apiToken.id });
  return { token, apiToken };
}
export async function listApiTokens(actor: Actor, orgId: OrgId, userId: UserId = actor.userId): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  if (userId !== actor.userId) assertCan(actor, "member:invite", { kind: "organization", orgId });
  return tokens.listTokens(orgId, userId);
}
export async function revokeApiToken(actor: Actor, orgId: OrgId, tokenId: string): Promise<ApiToken> {
  assertOrgScope(actor, orgId);
  const token = [REDACTED_SECRET] tokens.findToken(orgId, tokenId), "API token", tokenId);
  if (token.userId !== actor.userId) assertCan(actor, "member:invite", { kind: "organization", orgId });
  if (token.revokedAt !== null) return token;
  const revoked = await tokens.revoke(orgId, tokenId, toIsoTimestamp(new Date()));
  if (!revoked) return requireFound(await tokens.findToken(orgId, tokenId), "API token", tokenId);
  await emit("api_token.revoked", { ...actorEnvelope(actor), tokenId });
  return revoked;
}
export async function revokeMemberApiTokens(actor: Actor, userId: UserId): Promise<void> {
  const revoked = await tokens.revokeUserTokens(actor.orgId, userId, toIsoTimestamp(new Date()));
  for (const token of revoked) await emit("api_token.revoked", { ...actorEnvelope(actor), tokenId: token.id });
}
export async function authenticateApiToken(token: [REDACTED_SECRET] Promise<Actor | null> {
  const apiToken = await tokens.findByHash(hashToken(token));
  const now = toIsoTimestamp(new Date());
  if (!apiToken || apiToken.revokedAt !== null || apiToken.expiresAt <= now) return null;
  const org = await organizations.findOrgById(apiToken.orgId);
  if (!org || org.archivedAt !== null) return null;
  const actor = await resolveActor(apiToken.userId, apiToken.orgId);
  if (!actor) return null;
  await tokens.touch(apiToken.orgId, apiToken.id, now);
  return { userId: actor.userId, orgId: actor.orgId, role: apiToken.scope === "read" ? "viewer" : actor.role };
